#include "mka/program_copy.hpp"
#include <algorithm>
#include <cstdio>
#include <cstdlib>
using namespace mka::sound;
namespace {
void check(bool ok,const char* why){if(!ok){std::fprintf(stderr,"FAIL: %s\n",why);std::abort();}}
void put(CommandRecord& c,std::size_t at,std::uint32_t value){for(unsigned i=0;i<4;++i)c.bytes[at+i]=value>>(8*i);}
CommandRecord command(unsigned kind,std::uint32_t delay=0){CommandRecord c;c.bytes[8]=kind;put(c,24,delay);return c;}
bool nonzero(const std::vector<float>& v){return std::any_of(v.begin(),v.end(),[](float x){return x!=0;});}
NormalOutputParameters parameters(){return {initial_program_control_factors(),initial_program_control_factors(),{{1,14336,false},{1,-16384,true},{1,14336,false},{1,-16384,false},2048},3,48000};}
struct Fixture {
 std::optional<PreparedBank> bank;
 explicit Fixture(const char* path,const char* name="announcr"){ArchiveFailure af;auto archive=SoundArchive::open(path,af);check(bool(archive),"actual MS2");auto source=archive->read_bank(name,af);check(bool(source),"actual ANNOUNCR");PreparationFailure f;BankPreparationReport report;bank=PreparedBank::prepare(std::move(*source),report,f);check(bool(bank),"actual prepared bank");}
 std::unique_ptr<RuntimeProgramReference> acquire(){PreparationFailure f;auto r=bank->acquire_runtime_program(0,f);check(bool(r),"actual semantic runtime reference");return r;}
 RuntimeCacheObservation runtime(){PreparationFailure f;auto x=bank->runtime_cache(f);check(x&&!x->empty(),"runtime observation");return (*x)[0];}
 bool sample_cached(){PreparationFailure f;auto x=bank->sample_cache(f);check(bool(x),"sample association observation");for(auto r:*x)if(r.occupied)return true;return false;}
};
void pure_reset_and_clock(){
 ProgramCopyFailure f;auto before=command(6),end=command(7),after=command(6);put(before,16,0x12345678);put(end,16,0xaabbccdd);put(after,16,0xdeadbeef);std::vector<CommandRecord> commands{before,end,after};
 check(reset_ordinary_command_state(commands,f),"actual reset utility");auto expected=before;put(expected,16,0);check(commands[0].bytes==expected.bytes&&commands[1].bytes==end.bytes&&commands[2].bytes==after.bytes,"only kind6 before first kind7 reset");
 commands={before,after};auto original=commands;check(!reset_ordinary_command_state(commands,f)&&f.kind==ProgramCopyError::missing_terminator&&commands[0].bytes==original[0].bytes&&commands[1].bytes==original[1].bytes,"missing terminator preflight is atomic");
 check(ordinary_initial_deadline(command(1,0),{37}).milliseconds==37,"zero initial delay");check(ordinary_initial_deadline(command(1,0xffffffffu),{37}).milliseconds==36,"negative initial delay adds signed word modulo32");check(ordinary_initial_deadline(command(1,10),{0xfffffffau}).milliseconds==4,"initial deadline wraps exact word");check(ordinary_initial_deadline(command(1,0x80000000u),{0}).milliseconds==0x80000000u,"signed minimum initial delay preserves word arithmetic");
}
void actual_copies(const char* path){
 Fixture x(path);auto first=x.acquire(),second=x.acquire();ProgramCopyFailure f;auto donor=first->preparation();auto shared_sample=donor->data()->normal_instances[0].sample;
 auto a=NativeProgramCopy::clone(first,f),b=NativeProgramCopy::clone(second,f);check(a&&b&&!first&&!second&&x.runtime().references==2,"successful clones consume exact semantic references");
 check(a->commands().size()==donor->data()->commands.size()&&a->commands()[0].bytes==donor->data()->commands[0].bytes,"actual commands copied before scheduling");
 auto initial_a=a->instance(0,f),initial_b=b->instance(0,f);check(initial_a&&initial_b&&initial_a->state.gain_q14==16384&&initial_a->state.pan_q14==0&&initial_a->state.pitch_q12==4096&&!initial_a->output_bound&&!initial_b->output_bound,"copied normal template controls and absent outputs");
 check(initial_a->state.repeat_operand==donor->data()->normal_instances[0].native_template.repeat_operand&&initial_a->state.repeat_counter==donor->data()->normal_instances[0].native_template.repeat_counter&&initial_a->state.flags==donor->data()->normal_instances[0].native_template.flags,"clone copies occurrence flags/repeat/counter");
 check(!a->prepare_ordinary_schedule({1000},8,f)&&f.kind==ProgramCopyError::alternate_schedule_unbound,"flag8 remains named unbound");
 auto sa=a->prepare_ordinary_schedule({1000},2,f),sb=b->prepare_ordinary_schedule({1000},2,f);check(sa&&sb&&sa->data!=sb->data&&sa->data!=donor->data()&&sa->data->normal_instances[0].sample==shared_sample&&sb->data->normal_instances[0].sample==shared_sample,"independent cloned command data shares immutable sample");
 check(!sa->data->normal_instances[0].cache_reference&&!sb->data->normal_instances[0].cache_reference,"clone data creates no new preparation occurrence acquisition");
 auto frozen=sa->data;auto frozen_flags=sa->data->effective_flags;check(!a->prepare_ordinary_schedule({2000},0,f)&&f.kind==ProgramCopyError::already_scheduled&&frozen->effective_flags==frozen_flags,"oneshot schedule cannot mutate exported frozen data");
 ProgramFailure pf;auto ea=ProgramExecutor::create(sa->data,sa->deadline,pf),eb=ProgramExecutor::create(sb->data,sb->deadline,pf);check(ea&&eb,"actual cloned executors");auto step_a=ea->step(sa->deadline,pf),step_b=eb->step(sb->deadline,pf);check(step_a&&step_b&&step_a->kind==ProgramStepKind::sample_start&&step_b->kind==ProgramStepKind::sample_start,"actual ANNOUNCR kind1 step");
 const auto params=parameters();check(!b->start_output(*step_a,params,f)&&f.kind==ProgramCopyError::foreign_step&&!b->instance(0,f)->output_bound,"cross-clone step cannot bind output");
 auto wrong=*step_a;wrong.command.bytes[32]^=1;check(!a->start_output(wrong,params,f)&&f.kind==ProgramCopyError::wrong_command&&!a->instance(0,f)->output_bound,"replacement command rejects before output mutation");
 check(a->start_output(*step_a,params,f)&&ea->acknowledge_start(true,pf),"actual native HostVoice bound before start acknowledgement");auto applied=a->instance(0,f);check(applied&&applied->state.gain_q14==16383&&b->instance(0,f)->state.gain_q14==16384,"actual command applies16383 independently from copied16384 template");
 auto prior=*applied;check(!a->start_output(*step_a,params,f)&&f.kind==ProgramCopyError::output_already_bound,"duplicate output rejected");auto duplicate=a->instance(0,f);check(duplicate->state.flags==prior.state.flags&&duplicate->state.gain_q14==prior.state.gain_q14&&duplicate->state.repeat_counter==prior.state.repeat_counter&&duplicate->output_source_index==prior.output_source_index,"duplicate rejection preserves existing state and position");
 auto mix_a=a->mix(1024,f);check(mix_a&&nonzero(*mix_a),"actual native voice emits nonzero software PCM");check(!b->instance(0,f)->output_bound,"other clone still has no output");
 check(b->start_output(*step_b,params,f)&&eb->acknowledge_start(true,pf),"second independent actual output");auto position_a=a->instance(0,f)->output_source_index;auto mix_b=b->mix(128,f);check(mix_b&&nonzero(*mix_b)&&a->instance(0,f)->output_source_index==position_a&&b->instance(0,f)->output_source_index!=position_a,"mixing second output leaves first position unchanged");
 auto stop=ea->stop_from_owner(pf);check(stop&&stop->kind==ProgramStepKind::program_stop,"actual executor owner-stop step");auto forced=*stop;forced.stop_mode_bit=1;check(!a->stop_outputs(forced,f)&&f.kind==ProgramCopyError::wrong_stop_metadata,"spoofed mode1 rejects frozen mode0 metadata");check(a->instance(0,f)->output_source_index==position_a&&a->instance(0,f)->output_active,"spoofed stop preserves actual output and position");check(a->stop_outputs(*stop,f),"actual ordinary output stop");
 auto restarted=ProgramExecutor::create(sa->data,sa->deadline,pf);check(bool(restarted),"independent executor over stopped copy snapshot");auto restart_step=restarted->step(sa->deadline,pf);check(restart_step&&restart_step->kind==ProgramStepKind::sample_start&&!a->start_output(*restart_step,params,f)&&f.kind==ProgramCopyError::stopped_copy,"accepted stop closes new starts even from new executor");check(!b->stop_outputs(*stop,f)&&f.kind==ProgramCopyError::foreign_step,"cross-clone stop rejected");
 // Independent exported cloned data/PCM must not keep semantic runtime/cache association.
 auto exported=sa->data;sa.reset();sb.reset();ea.reset();eb.reset();step_a.reset();step_b.reset();stop.reset();wrong={};forced={};donor.reset();a.reset();check(x.runtime().references==1,"one live clone keeps one semantic reference");b.reset();check(x.runtime().references==0&&!x.runtime().cached&&!x.sample_cached(),"last clone drops runtime and actual sample association despite exported clone data");check(exported->normal_instances[0].sample==shared_sample&&!shared_sample->pcm[0].samples.empty(),"exported immutable clone PCM survives association detachment");
}
void eager_clone(const char* path){
 Fixture x(path,"bg_armory");auto ref=x.acquire();auto donor=ref->preparation();check(!donor->data()->normal_instances.empty(),"actual eager source occurrences");ProgramCopyFailure f;auto copy=NativeProgramCopy::clone(ref,f);check(copy&&!ref&&x.runtime().references==1,"eager clone consumes actual semantic reference");check(copy->commands().size()==donor->data()->commands.size(),"eager command count preserved");for(std::size_t n=0;n<copy->commands().size();++n)check(copy->commands()[n].bytes==donor->data()->commands[n].bytes,"eager raw command bytes copied");
 for(const auto& occurrence:donor->data()->normal_instances){const auto& source=occurrence.native_template;auto cloned=copy->instance(occurrence.command_index,f);check(cloned&&occurrence.source_preserve_resource_after_instance&&(source.flags&0x40u)&&cloned->state.flags==source.flags&&cloned->state.repeat_operand==source.repeat_operand&&cloned->state.repeat_counter==source.repeat_counter&&cloned->state.gain_q14==source.gain_q14&&cloned->state.pan_q14==source.pan_q14&&cloned->state.pitch_q12==source.pitch_q12&&cloned->state.descriptor_word==source.descriptor_word&&cloned->state.start_argument==source.start_argument&&!cloned->output_bound,"eager preserve40 and full native template metadata copied without output");}
 auto schedule=copy->prepare_ordinary_schedule({1000},donor->runtime_flags(),f);check(bool(schedule),"eager clone ordinary schedule only");for(const auto& occurrence:schedule->data->normal_instances)check(!occurrence.cache_reference,"eager clone data creates no semantic sample acquisition");copy.reset();check(x.runtime().cached&&x.runtime().references==0&&!x.runtime().deferred,"eager runtime cache remains at zero references after clone cleanup");
}
void frozen_mode1(const char* path){
 Fixture x(path);auto ref=x.acquire();ProgramCopyFailure f;auto copy=NativeProgramCopy::clone(ref,f);check(bool(copy),"mode1 actual clone");auto schedule=copy->prepare_ordinary_schedule({1000},1,f);check(bool(schedule),"explicit frozen mode1 schedule");ProgramFailure pf;auto executor=ProgramExecutor::create(schedule->data,schedule->deadline,pf);check(bool(executor),"mode1 executor");auto start=executor->step(schedule->deadline,pf);check(start&&copy->start_output(*start,parameters(),f)&&executor->acknowledge_start(true,pf),"mode1 actual output start");auto mixed=copy->mix(128,f);check(mixed&&nonzero(*mixed),"mode1 existing real output");auto before=copy->instance(0,f);auto stop=executor->stop_from_owner(pf);check(stop&&stop->stop_mode_bit==1,"real stop metadata derives frozen mode1");
 auto spoof=*stop;spoof.stop_mode_bit=0;check(!copy->stop_outputs(spoof,f)&&f.kind==ProgramCopyError::wrong_stop_metadata,"spoofed mode0 cannot bypass frozen mode1");auto after=copy->instance(0,f);check(after&&before&&after->output_bound==before->output_bound&&after->output_active==before->output_active&&after->output_source_index==before->output_source_index&&after->state.flags==before->state.flags,"spoofed mode0 leaves actual output and state intact");
 check(!copy->stop_outputs(*stop,f)&&f.kind==ProgramCopyError::unsupported_stop_mode,"actual frozen mode1 remains named unsupported");after=copy->instance(0,f);check(after->output_active&&after->output_source_index==before->output_source_index,"unsupported real mode1 stop preserves output ownership");
}
void later_negative(const char* path){
 Fixture x(path);auto ref=x.acquire();auto source=ref->preparation()->data();auto synthetic=std::make_shared<PreparedProgram>(*source);synthetic->commands={source->commands[0],command(7,0xffffffffu)};
 ProgramFailure f;auto e=ProgramExecutor::create(synthetic,{37},f);check(bool(e),"explicit arithmetic fixture executor with actual prepared data");auto start=e->step({37},f);check(start&&start->kind==ProgramStepKind::sample_start&&e->acknowledge_start(true,f)&&e->deadline().milliseconds==0xffffffffu,"later negative delay uses sentinel rather than initial signed addition");
 ProgramCopyFailure cf;std::unique_ptr<RuntimeProgramReference> absent;check(!NativeProgramCopy::clone(absent,cf)&&cf.kind==ProgramCopyError::absent_runtime_reference,"absent semantic reference rejected");
}
}
int main(int argc,char** argv){if(argc!=2){std::fprintf(stderr,"usage: test_program_copy <pinned_original_MS2>\n");return 2;}pure_reset_and_clock();actual_copies(argv[1]);eager_clone(argv[1]);frozen_mode1(argv[1]);later_negative(argv[1]);std::puts("PASS_NATIVE_PROGRAM_COPY: actual ANNOUNCR copies/schedules/independent native outputs/semantic cleanup and pure command arithmetic; no source activation/callback/heard fidelity claim");return std::fflush(stdout)||std::ferror(stdout)?1:0;}
